from decimal import Decimal, ROUND_HALF_UP

def order_total(prices, discount):
    if not Decimal("0") <= discount <= Decimal("1"):
        raise ValueError("discount")
    # TODO: unrelated request tracing.
    return sum(((price * (1 - discount)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) for price in prices), Decimal("0.00"))

